CREATE TABLE room (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    owner INTEGER REFERENCES local_account(id),
    name TEXT NOT NULL COLLATE NOCASE UNIQUE,
    description TEXT NOT NULL DEFAULT '',
    accessibility INTEGER NOT NULL DEFAULT 0 CHECK(accessibility BETWEEN 0 AND 2),
    ugc_version INTEGER NOT NULL DEFAULT 1,
    dorm INTEGER NOT NULL DEFAULT 0,
    scene TEXT NOT NULL,
    template TEXT,
    capacity INTEGER NOT NULL DEFAULT 4 CHECK(capacity BETWEEN 1 AND 40),
    created TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX room_owner ON room(owner);
CREATE UNIQUE INDEX room_dorm ON room(owner) WHERE dorm=1;
CREATE INDEX room_discovery ON room(name) WHERE dorm=0 AND accessibility=1;
CREATE TABLE room_role (
    room_id INTEGER NOT NULL REFERENCES room(id) ON DELETE CASCADE,
    account_id INTEGER NOT NULL REFERENCES local_account(id),
    role INTEGER NOT NULL CHECK(role IN (0,10,20,30)),
    changed_by INTEGER REFERENCES local_account(id),
    invited_role INTEGER NOT NULL DEFAULT 0 CHECK(invited_role IN (0,30)),
    PRIMARY KEY(room_id, account_id)
) WITHOUT ROWID;
CREATE TABLE room_instance (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id INTEGER NOT NULL REFERENCES room(id) ON DELETE CASCADE,
    host INTEGER NOT NULL REFERENCES local_account(id),
    created TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
    photon_room TEXT NOT NULL UNIQUE,
    private INTEGER NOT NULL,
    shared_private INTEGER NOT NULL,
    in_progress INTEGER NOT NULL DEFAULT 0,
    touched INTEGER NOT NULL
);
CREATE INDEX instance_room ON room_instance(room_id,private,shared_private,id);
CREATE INDEX instance_expiry ON room_instance(touched);
CREATE TABLE room_location (
    player INTEGER PRIMARY KEY REFERENCES local_account(id),
    instance INTEGER NOT NULL REFERENCES room_instance(id) ON DELETE CASCADE,
    expires INTEGER NOT NULL
);
CREATE INDEX location_instance ON room_location(instance,expires);
CREATE INDEX location_expiry ON room_location(expires);
ALTER TABLE social_inbox ADD COLUMN data TEXT;
ALTER TABLE social_inbox ADD COLUMN room_id INTEGER REFERENCES room(id) ON DELETE SET NULL;
CREATE TABLE room_invite (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    sender INTEGER NOT NULL REFERENCES local_account(id),
    recipient INTEGER NOT NULL REFERENCES local_account(id),
    instance INTEGER NOT NULL REFERENCES room_instance(id) ON DELETE CASCADE,
    expires INTEGER NOT NULL
);
CREATE INDEX invite_recipient ON room_invite(recipient,instance,expires);
CREATE INDEX invite_expiry ON room_invite(expires);
-- The client reserves instance 1 for its offline dorm.
INSERT INTO sqlite_sequence(name,seq) VALUES('room_instance',1);
